    <div v-else class="saved-target"><span>{{tr('要查找的单位或业务','Organization or business to find')}}</span><strong>{{savedOrganization}}</strong><button v-if="!readOnly" class="text-button" :disabled="busy||working" data-ai-action="edit-target" @click="beginTargetEdit">{{tr('修改','Edit')}}</button></div>
    <button v-if="editingTarget" class="text-button cancel-target" :disabled="busy||working" data-ai-action="cancel-target" @click="cancelTargetEdit">{{tr('取消修改','Cancel edit')}}</button>
   </div>
   <div class="primary-actions">
    <button v-if="showPrimaryRead" v-refresh-feedback="{scope:projectId,busy:reading,error:readError}" class="button primary" :disabled="reading||busy" data-ai-action="retry-read" @click="load()"><RefreshCw :size="16"/>{{reading?tr('正在读取…','Reading…'):tr('重试读取','Retry read')}}</button>
    <button v-else-if="showPrimaryStart" class="button primary" :disabled="busy||reading||!organization.trim()" data-ai-action="start" @click="control('start',freeContinuation)"><Play :size="16"/>{{busy?tr('正在接续…','Continuing…'):mainLabel}}</button>
    <button v-if="working&&!readOnly" class="button ghost" :disabled="busy||phase==='pausing'||enrichment?.run?.status==='pausing'" data-ai-action="pause" @click="control('pause')"><Pause :size="15"/>{{tr('暂停','Pause')}}</button>
    <button v-if="run||pipeline||assist?.hasLocalAssets" class="button ghost" data-ai-action="results" @click="emit('results')">{{tr('查看资产','View assets')}}<ArrowRight :size="14"/></button>
   </div>
  </div>
  <p class="ai-next-step" role="status">{{summary}}</p>
  <div class="run-context" v-if="pipeline"><span>{{tr(`第 ${pipeline.round||1} 轮`,`Round ${pipeline.round||1}`)}}</span><span v-if="pipeline.collectionRunId">{{tr(`FOFA 任务 #${pipeline.collectionRunId}`,`FOFA job #${pipeline.collectionRunId}`)}}</span><span v-if="existingRoots.length">{{tr(`已允许 ${existingRoots.slice(0,2).join('、')}${existingRoots.length>2?' 等 '+existingRoots.length+' 个范围':''}`,`Allowed: ${existingRoots.slice(0,2).join(', ')}${existingRoots.length>2?' ('+existingRoots.length+' scopes in total)':''}`)}}</span></div>
  <dl v-if="assist" class="discovery-metrics" :aria-label="tr('发现概览','Discovery overview')"><div><dt :title="tr('项目中的历史记录，包含隔离与回收记录；不等于已确认资产数','Historical records in this project, including quarantined and trashed ones; not the number of confirmed assets')">{{tr('项目记录','Project records')}}</dt><dd>{{projectAssetCount==null?'—':projectAssetCount.toLocaleString()}}</dd></div><div><dt>{{tr('本轮新增','Added this round')}}</dt><dd>{{pipeline?.counts?.roundAdded==null?'—':pipeline.counts.roundAdded.toLocaleString()}}</dd></div><div><dt>{{tr('需要你决定','Needs your decision')}}</dt><dd>{{proposalFamilyCount+conflictCount}}<button v-if="conflictCount" class="text-button" :aria-expanded="showConflicts" data-ai-action="review-conflicts" @click="showConflicts=!showConflicts">{{tr('查看冲突','View conflicts')}}<ArrowRight :size="13"/></button></dd><small>{{tr(`${proposalFamilyCount} 组新增范围 · ${conflictCount} 组冲突`,`${proposalFamilyCount} new scope groups · ${conflictCount} conflicts`)}}</small></div></dl>
