   <span v-else class="hunter-mode">{{pipeline?.allowHunter?tr('Hunter 精确扩展已启用','Hunter precise expansion on'):tr('Hunter 未启用','Hunter off')}}</span>
   <span v-if="knownHunterCost" class="hunter-cost">{{tr(`已知消耗 ${pipeline!.hunter.spentPoints!.toLocaleString()} 积分`,`Known cost: ${pipeline!.hunter.spentPoints!.toLocaleString()} points`)}}</span><span v-else-if="pipeline?.allowHunter" class="hunter-cost">{{tr('积分回执尚未返回','Points receipt not returned yet')}}</span>
   <span v-if="hunterReceiptUnknown" class="hunter-receipt">{{tr('部分扣费或请求结果未知，Hunter 已暂停；可继续免费发现，原回执保留。','Some charges or request results are unknown, so Hunter is paused. You can continue with free discovery; the original receipt is kept.')}}</span>
   <span v-if="!hunterReady" class="hunter-setup">{{!hunterReadinessKnown?tr('Hunter 账户状态尚未读到，付费关联保持关闭，可继续免费发现。','Hunter account status hasn’t loaded yet. Paid matching stays off; you can continue with free discovery.'):tr(`Hunter 尚未就绪：${!assist?.readiness?.hunter.keyConfigured?'需要保存 Key':'需要确认接口配置'}。`,`Hunter isn’t ready: ${!assist?.readiness?.hunter.keyConfigured?'save an API key':'confirm the API configuration'}.`)}}<button v-if="!readOnly&&hunterReadinessKnown" class="text-button" data-ai-action="configure" @click="configureHunter">{{tr('前往配置','Configure')}}</button></span>
  </div>
  <section v-if="visibleProposal&&eligibleGroups.length" class="ai-scope-confirm" :aria-label="tr('统一确认发现范围','Confirm discovery scope')">
   <div class="scope-heading"><div><h3>{{readOnly?tr('历史范围建议','Past scope suggestions'):tr('只需确认新增范围','Confirm only the new scope')}}</h3><p>{{tr(`已核验的范围建议 · ${eligibleGroups.length} 个域名家族；同一家族的相关证书一起处理。`,`Verified scope suggestions · ${eligibleGroups.length} domain families; related certificates in a family are handled together.`)}}</p></div><span class="scope-count">{{tr(`已选 ${selectedHosts.length} 个具体范围`,`${selectedHosts.length} specific scopes selected`)}}</span></div>
   <div class="scope-preview"><span v-for="group in eligibleGroups.slice(0,3)" :key="group.root">{{group.root}}<small v-if="group.shared">{{tr(`仅 ${group.scopes.length} 个具体主机`,`Only ${group.scopes.length} specific hosts`)}}</small></span><span v-if="eligibleGroups.length>3">{{tr(`另 ${eligibleGroups.length-3} 组`,`${eligibleGroups.length-3} more groups`)}}</span></div>
   <details class="scope-adjust" :open="showScopeDetails" @toggle="showScopeDetails=($event.target as HTMLDetailsElement).open"><summary>{{tr(`查看或调整建议 · 已选 ${selectedFamilies.length} / ${eligibleGroups.length} 组`,`View or adjust suggestions · ${selectedFamilies.length} / ${eligibleGroups.length} groups selected`)}}</summary><div v-if="showScopeDetails" class="scope-family-list"><article v-for="group in eligibleGroups" :key="group.root"><label class="scope-family-choice"><input v-model="selectedFamilies" type="checkbox" :value="group.root" :disabled="busy||readOnly||statusUncertain"/><span><strong>{{group.root}}</strong><small>{{tr(`${group.assetCount.toLocaleString()} 条关联资产 · ${group.evidenceGroups} 组证据${group.shared?' · 共享平台，仅 '+group.scopes.length+' 个具体主机':''}`,`${group.assetCount.toLocaleString()} linked assets · ${group.evidenceGroups} evidence groups${group.shared?' · Shared platform, only '+group.scopes.length+' specific hosts':''}`)}}</small></span></label><div class="scope-verification"><p v-for="(source,index) in group.verification?.sources" :key="index">{{sourceLabel(source.kind)}} · {{source.host}} · {{source.organization||tr('已确认的域名绑定','Confirmed domain binding')}}<template v-if="source.assetId"> · {{tr(`资产 #${source.assetId}`,`Asset #${source.assetId}`)}}</template><small v-if="source.validUntil"> · {{tr(`证书有效至 ${source.validUntil}`,`Certificate valid until ${source.validUntil}`)}}</small><small v-if="source.sourceUrl" class="verification-source-url">{{source.sourceUrl}}</small></p></div><details class="scope-boundary"><summary>{{tr('范围与证据','Scope and evidence')}}</summary><p>{{tr(`仅确认以下范围（及其子域）：${group.scopes.join('、')}`,`Confirms only these scopes (and their subdomains): ${group.scopes.join(', ')}`)}}</p><p>{{tr(`已观察名称示例：${group.observedDomains.join('、')}`,`Observed name examples: ${group.observedDomains.join(', ')}`)}}</p><p v-if="group.reasons.length">{{tr(`AI 推断（不作核验依据）：${group.reasons.join('；')}`,`AI inference (not verification evidence): ${group.reasons.join('; ')}`)}}</p><p v-if="group.conflictGroups">{{tr(`${group.conflictGroups} 组排除或身份冲突保留原结论，不会据此恢复资产。`,`${group.conflictGroups} exclusion or identity-conflict groups keep their original decision; no assets are restored from them.`)}}</p></details></article></div></details>
   <p v-if="!readOnly" class="scope-authorization">{{tr(`点击确认，表示所选 ${selectedHosts.length} 个范围及其子域属于本次允许探测的范围。`,`By confirming, you authorize probing of the ${selectedHosts.length} selected scopes and their subdomains for this run.`)}}</p>
