   <article v-for="item in certificateConflicts" :key="item.kind+item.identity"><strong>{{tr('证书与主机身份不一致','Certificate and host identity mismatch')}}</strong><p>{{item.hosts.join(tr('、',', '))}}{{item.hostCount&&item.hostCount>item.hosts.length?tr(` 等 ${item.hostCount} 个主机`,` (${item.hostCount} hosts in total)`):''}}</p><p>{{item.detail}}</p><details><summary>{{tr('证书标识','Certificate identity')}}</summary><p>{{item.identity}}</p></details><button class="button ghost compact" :disabled="busy||readOnly||statusUncertain" @click="acknowledgeCertificate(item)">{{tr('我已了解，保留冲突记录','Got it, keep the conflict record')}}</button></article>
   <p v-if="(assist?.review.run?.queueCounts?.conflict||0)>conflicts.length">{{tr('更多冲突保留在完整证据记录中。','More conflicts are kept in the full evidence record.')}}</p>
  </section>
  <p v-if="notice" class="ai-notice" role="status">{{notice}}</p><p v-if="error||readError||assist?.enrichmentError" class="form-error" role="alert">{{error||readError||assist?.enrichmentError}}</p>
  <div class="discovery-secondary"><button class="text-button" :aria-expanded="showSettings" data-ai-action="options" @click="showSettings=!showSettings">{{showSettings?tr('收起发现设置','Hide discovery settings'):tr('发现设置','Discovery settings')}}</button><button v-if="run||pipeline" class="text-button" :aria-expanded="showProcess" data-ai-action="process" @click="showProcess=!showProcess">{{showProcess?tr('收起过程与用量','Hide process and usage'):tr('过程与用量','Process and usage')}}</button></div>
  <section v-if="showSettings" class="ai-details discovery-settings" :aria-label="tr('发现设置','Discovery settings')">
   <p>{{tr('默认复用项目已有资产；新项目自动先采集 FOFA。只有需要更换采集条件时才修改下方选项。','Existing project assets are reused by default; new projects collect from FOFA first. Change the options below only when you need different collection criteria.')}}</p>
   <label v-if="!needsInitialCollection" class="discovery-option"><input v-model="collectFirst" type="checkbox" :disabled="!optionsEditable"/><span>{{tr('重新采集 FOFA，再开始新一轮发现','Re-collect from FOFA, then start a new discovery round')}}<small>{{tr('原资产与历史保留；不勾选则沿用当前任务和证据。','Existing assets and history are kept. Leave unchecked to reuse the current task and evidence.')}}</small></span></label>
   <label class="field collection-targets"><span>{{tr('FOFA 初始种子（可选，每行一个单位、域名、IP 或网段）','Initial FOFA seeds (optional; one organization, domain, IP or CIDR per line)')}}</span><textarea v-model="collectionTargets" rows="3" :disabled="!optionsEditable" :placeholder="tr('例如：10086.cn\n留空时按目标单位搜索','e.g. example.com\nLeave blank to search by the target organization')"/><small>{{needsInitialCollection||collectFirst?tr('此次采集会使用这些种子。','This collection will use these seeds. '):tr('仅在勾选重新采集 FOFA 后使用。','Used only when re-collecting from FOFA is checked. ')}}{{tr('检索种子不自动成为探测授权。','Search seeds don’t automatically authorize probing.')}}</small></label>
   <label class="discovery-option"><input v-model="includeIsolated" type="checkbox" :disabled="!optionsEditable"/><span>{{tr('分析时包含隔离及回收记录','Include quarantined and trashed records in analysis')}}<small>{{tr('只读提取证据，不自动恢复资产。','Evidence is read only; assets are not restored automatically.')}}</small></span></label>
   <p>{{tr('AI 使用当前聊天模型。Hunter 仅在明确启用后查询，可使用全部免费与权益积分；仅使用核验通过的证书指纹、域名或 CNAME，结果与扣费未知时不自动重发。','AI uses the current chat model. Hunter queries only when explicitly enabled and can use all free and bonus points. It uses only verified certificate fingerprints, domains or CNAMEs, and doesn’t resend automatically when results or charges are unknown.')}}</p>
  </section>
  <section v-if="showProcess&&(run||pipeline)" class="ai-details discovery-process" :aria-label="tr('发现过程与用量','Discovery process and usage')">
   <DiscoveryPipelineProgress v-if="pipeline" :pipeline="pipeline"/>
   <p v-if="run">{{tr(`当前项目 · ${run.processedAssets.toLocaleString()} / ${run.totalAssets.toLocaleString()} 条资产 · 已整理证据 ${run.groups.toLocaleString()} 组`,`Current project · ${run.processedAssets.toLocaleString()} / ${run.totalAssets.toLocaleString()} assets · ${run.groups.toLocaleString()} evidence groups organized`)}}</p>
   <p v-if="run">{{tr(`此审阅任务累计：${run.requests} 次请求，输入 ${run.inputTokens.toLocaleString()} / 输出 ${run.outputTokens.toLocaleString()} Token${run.unknownRequests?'；'+run.unknownRequests+' 次结果未知，不自动重发':''}。${run.model}`,`This review task so far: ${run.requests} requests, ${run.inputTokens.toLocaleString()} input / ${run.outputTokens.toLocaleString()} output tokens${run.unknownRequests?'; '+run.unknownRequests+' with unknown results, not resent automatically':''}. ${run.model}`)}}</p>
   <p v-if="proposalDiagnostics">{{proposalDiagnostics.networkVerified?tr('本次包含公开 CT 叶证书核验；证书证据不代表主机当前存活，新增探测范围仍需确认。','This run includes public CT leaf certificate checks. Certificate evidence doesn’t mean a host is live now; new probe scope still needs confirmation.'):tr('本次仅核验本地证据，未联网查证企业归属。','This run verified local evidence only and didn’t check company ownership online.')}}</p>
   <p v-if="proposalDiagnostics?.removedNoLiveEvidence">{{tr(`已省略 ${proposalDiagnostics.removedNoLiveEvidence} 项只有历史或已失效证据的范围，原记录保留。`,`Omitted ${proposalDiagnostics.removedNoLiveEvidence} scopes with only historical or expired evidence; original records are kept.`)}}</p>
